1	<?php
2	
3	declare(strict_types=1);
4	
5	/**
6	 * iHymns — Parent Songbooks schema (#782 phase A)
7	 *
8	 * Copyright (c) 2026 iHymns. All rights reserved.
9	 *
10	 * PURPOSE:
11	 * Some songbooks aren't standalone collections — they're either:
12	 *
13	 *   (1) Translated derivatives of a canonical parent (e.g. the
14	 *       22 vernacular Christ in Song hymnals → English CIS), OR
15	 *
16	 *   (2) Editions in a chain (e.g. Mission Praise 1, 2, Combined),
17	 *       OR
18	 *
19	 *   (3) Volumes in a peer-to-peer series (e.g. Songs of Fellowship
20	 *       vols 1, 2, 3, … with no canonical root).
21	 *
22	 * Cases (1) and (2) are HIERARCHICAL — there's a real canonical
23	 * row to point upward to — so they fit a self-FK on tblSongbooks
24	 * (ParentSongbookId + ParentRelationship). Case (3) is PEER-TO-PEER
25	 * — no canonical root, just shared series identity — so it fits a
26	 * series-membership join table (tblSongbookSeries +
27	 * tblSongbookSeriesMembership).
28	 *
29	 * A songbook can carry BOTH: e.g. Mission Praise vol 2 has
30	 * ParentSongbookId = MP-vol-1 (it's the next edition) AND a row
31	 * in tblSongbookSeriesMembership linking to "Mission Praise series"
32	 * (so a consumer asking "what other Mission Praise volumes exist?"
33	 * gets the whole canon). The two relationships answer different
34	 * questions:
35	 *
36	 *   - Parent FK   → "Where's the canonical reference for this row?"
37	 *   - Series link → "What other songbooks share my collection
38	 *                    identity?"
39	 *
40	 * Phase A is schema only — phases B-E (separate PRs) wire the
41	 * admin picker, public-side display, helpers, and bulk-import
42	 * auto-link on top.
43	 *
44	 * Idempotent — INFORMATION_SCHEMA-probed; re-runs are no-ops.
45	 *
46	 * USAGE:
47	 *   CLI: php appWeb/.sql/migrate-parent-songbooks.php
48	 *   Web: /manage/setup-database → "Parent Songbooks (#782 phase A)"
49	 *        (entry point requires global_admin)
50	 */
51	
52	if (PHP_SAPI === 'cli') {
53	    if (!function_exists('getDbMysqli')) {
54	        require_once dirname(__DIR__) . '/public_html/includes/db_mysql.php';
55	    }
56	    $isCli = true;
57	} else {
58	    if (!defined('IHYMNS_SETUP_DASHBOARD')) {
59	        if (!function_exists('isAuthenticated')) {
60	            require_once dirname(__DIR__) . '/public_html/manage/includes/auth.php';
61	        }
62	        if (!isAuthenticated()) {
63	            http_response_code(401);
64	            exit('Authentication required.');
65	        }
66	        $u = getCurrentUser();
67	        if (!$u || $u['role'] !== 'global_admin') {
68	            http_response_code(403);
69	            exit('Global admin required.');
70	        }
71	    }
72	    if (!function_exists('getDbMysqli')) {
73	        require_once dirname(__DIR__) . '/public_html/includes/db_mysql.php';
74	    }
75	    $isCli = false;
76	}
77	
78	function _migParentSb_out(string $line): void
79	{
80	    global $isCli;
81	    echo $line . ($isCli ? "\n" : "<br>\n");
82	    if ($isCli) flush();
83	}
84	
85	function _migParentSb_tableExists(mysqli $db, string $table): bool
86	{
87	    $stmt = $db->prepare(
88	        'SELECT 1 FROM INFORMATION_SCHEMA.TABLES
89	          WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? LIMIT 1'
90	    );
91	    $stmt->bind_param('s', $table);
92	    $stmt->execute();
93	    $exists = $stmt->get_result()->fetch_row() !== null;
94	    $stmt->close();
95	    return $exists;
96	}
97	
98	function _migParentSb_columnExists(mysqli $db, string $table, string $column): bool
99	{
100	    $stmt = $db->prepare(
101	        'SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
102	          WHERE TABLE_SCHEMA = DATABASE()
103	            AND TABLE_NAME   = ?
104	            AND COLUMN_NAME  = ?
105	          LIMIT 1'
106	    );
107	    $stmt->bind_param('ss', $table, $column);
108	    $stmt->execute();
109	    $exists = $stmt->get_result()->fetch_row() !== null;
110	    $stmt->close();
111	    return $exists;
112	}
113	
114	_migParentSb_out('Parent Songbooks schema migration starting (#782 phase A)…');
115	
116	$db = getDbMysqli();
117	if (!$db) {
118	    _migParentSb_out('ERROR: could not connect to database.');
119	    exit(1);
120	}
121	
122	if (!_migParentSb_tableExists($db, 'tblSongbooks')) {
123	    _migParentSb_out('ERROR: tblSongbooks not found. Run install.php first.');
124	    exit(1);
125	}
126	
127	/* =========================================================================
128	 * Step 1 — tblSongbooks.ParentSongbookId + ParentRelationship columns
129	 * ========================================================================= */
130	if (_migParentSb_columnExists($db, 'tblSongbooks', 'ParentSongbookId')) {
131	    _migParentSb_out('[skip] tblSongbooks.ParentSongbookId already present.');
132	} else {
133	    $sql = "ALTER TABLE tblSongbooks
134	            ADD COLUMN ParentSongbookId INT UNSIGNED NULL DEFAULT NULL
135	                COMMENT 'Canonical parent songbook for translations / editions; NULL = standalone or peer-grouped via tblSongbookSeriesMembership',
136	            ADD KEY idx_ParentSongbookId (ParentSongbookId)";
137	    if (!$db->query($sql)) {
138	        _migParentSb_out('ERROR: adding ParentSongbookId failed: ' . $db->error);
139	        exit(1);
140	    }
141	    _migParentSb_out('[add ] tblSongbooks.ParentSongbookId.');
142	}
143	
144	if (_migParentSb_columnExists($db, 'tblSongbooks', 'ParentRelationship')) {
145	    _migParentSb_out('[skip] tblSongbooks.ParentRelationship already present.');
146	} else {
147	    /* Enum values:
148	         translation — vernacular derived from a canonical parent
149	                       (e.g. Spanish CIS → English CIS).
150	         edition     — a successor edition in a chain
151	                       (e.g. Mission Praise 2 → Mission Praise 1).
152	         abridgement — a curated subset of a canonical parent
153	                       (e.g. Children's Mission Praise → Mission Praise).
154	       Reserved for v2: peer relationships are modelled via the
155	       series tables below, NOT here. */
156	    $sql = "ALTER TABLE tblSongbooks
157	            ADD COLUMN ParentRelationship ENUM('translation','edition','abridgement') NULL DEFAULT NULL
158	                COMMENT 'How this row relates to its parent — drives display copy + linkage UI'
159	                AFTER ParentSongbookId";
160	    if (!$db->query($sql)) {
161	        _migParentSb_out('ERROR: adding ParentRelationship failed: ' . $db->error);
162	        exit(1);
163	    }
164	    _migParentSb_out('[add ] tblSongbooks.ParentRelationship.');
165	}
166	
167	/* The FK lives at the end so the columns are guaranteed to exist
168	   first. ON DELETE SET NULL keeps a child row alive when the parent
169	   is removed (the relationship is informational; orphan rows aren't
170	   broken data). ON UPDATE CASCADE so a future Id reassignment (rare)
171	   doesn't strand children. */
172	$stmt = $db->prepare(
173	    "SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS
174	      WHERE TABLE_SCHEMA = DATABASE()
175	        AND TABLE_NAME   = 'tblSongbooks'
176	        AND CONSTRAINT_NAME = 'fk_songbooks_parent'
177	      LIMIT 1"
178	);
179	$stmt->execute();
180	$fkExists = $stmt->get_result()->fetch_row() !== null;
181	$stmt->close();
182	if ($fkExists) {
183	    _migParentSb_out('[skip] FK fk_songbooks_parent already present.');
184	} else {
185	    $sql = "ALTER TABLE tblSongbooks
186	            ADD CONSTRAINT fk_songbooks_parent FOREIGN KEY (ParentSongbookId)
187	                REFERENCES tblSongbooks(Id)
188	                ON DELETE SET NULL ON UPDATE CASCADE";
189	    if (!$db->query($sql)) {
190	        _migParentSb_out('WARN: FK fk_songbooks_parent could not be added: ' . $db->error);
191	        _migParentSb_out('       The column exists; the FK is enforcement-only and the migration continues.');
192	    } else {
193	        _migParentSb_out('[add ] FK fk_songbooks_parent.');
194	    }
195	}
196	
197	/* =========================================================================
198	 * Step 2 — tblSongbookSeries
199	 * ========================================================================= */
200	if (_migParentSb_tableExists($db, 'tblSongbookSeries')) {
201	    _migParentSb_out('[skip] tblSongbookSeries already exists.');
202	} else {
203	    $sql = "CREATE TABLE tblSongbookSeries (
204	        Id           INT UNSIGNED  AUTO_INCREMENT PRIMARY KEY,
205	        Name         VARCHAR(120)  NOT NULL,
206	        Description  VARCHAR(255)  NOT NULL DEFAULT '',
207	        Slug         VARCHAR(120)  NOT NULL UNIQUE
208	                     COMMENT 'URL-safe lowercase form for /series/<slug> public listing pages',
209	        CreatedAt    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
210	        KEY idx_Name (Name)
211	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
212	    if (!$db->query($sql)) {
213	        _migParentSb_out('ERROR: create tblSongbookSeries failed: ' . $db->error);
214	        exit(1);
215	    }
216	    _migParentSb_out('[add ] tblSongbookSeries.');
217	}
218	
219	/* =========================================================================
220	 * Step 3 — tblSongbookSeriesMembership
221	 * ========================================================================= */
222	if (_migParentSb_tableExists($db, 'tblSongbookSeriesMembership')) {
223	    _migParentSb_out('[skip] tblSongbookSeriesMembership already exists.');
224	} else {
225	    $sql = "CREATE TABLE tblSongbookSeriesMembership (
226	        SeriesId     INT UNSIGNED NOT NULL,
227	        SongbookId   INT UNSIGNED NOT NULL,
228	        SortOrder    SMALLINT     NOT NULL DEFAULT 0
229	                     COMMENT 'Display order within the series (e.g. volume 1 → 10, volume 2 → 20, …)',
230	        Note         VARCHAR(120) NOT NULL DEFAULT ''
231	                     COMMENT 'Optional free-text annotation, e.g. \"published 1998\" or \"combined edition\"',
232	        CreatedAt    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
233	        PRIMARY KEY (SeriesId, SongbookId),
234	        KEY idx_member (SongbookId),
235	        CONSTRAINT fk_sbsm_series   FOREIGN KEY (SeriesId)
236	            REFERENCES tblSongbookSeries(Id) ON DELETE CASCADE,
237	        CONSTRAINT fk_sbsm_songbook FOREIGN KEY (SongbookId)
238	            REFERENCES tblSongbooks(Id)      ON DELETE CASCADE
239	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
240	    if (!$db->query($sql)) {
241	        _migParentSb_out('ERROR: create tblSongbookSeriesMembership failed: ' . $db->error);
242	        exit(1);
243	    }
244	    _migParentSb_out('[add ] tblSongbookSeriesMembership.');
245	}
246	
247	/* =========================================================================
248	 * Final probe
249	 * ========================================================================= */
250	$res = $db->query('SELECT COUNT(*) FROM tblSongbookSeries');
251	$seriesCount = $res ? (int)$res->fetch_row()[0] : 0;
252	if ($res) $res->close();
253	$res = $db->query('SELECT COUNT(*) FROM tblSongbookSeriesMembership');
254	$membershipCount = $res ? (int)$res->fetch_row()[0] : 0;
255	if ($res) $res->close();
256	$res = $db->query('SELECT COUNT(*) FROM tblSongbooks WHERE ParentSongbookId IS NOT NULL');
257	$linkedCount = $res ? (int)$res->fetch_row()[0] : 0;
258	if ($res) $res->close();
259	_migParentSb_out("Catalogue currently has {$linkedCount} songbook(s) with a parent link, "
260	               . "{$seriesCount} series defined, {$membershipCount} membership row(s).");
261	_migParentSb_out('Phases B-E (admin picker, public surfaces, helpers, bulk-import auto-link) are tracked in #782.');
262	
263	_migParentSb_out('Parent Songbooks schema migration finished (#782 phase A).');
