1	<?php
2	
3	declare(strict_types=1);
4	
5	/**
6	 * iHymns — Admin: Songbooks
7	 *
8	 * CRUD surface for `tblSongbooks`. Gated by the `manage_songbooks`
9	 * entitlement. Safe-guards:
10	 *   - Abbreviation is the natural key on tblSongs.SongbookAbbr — renaming
11	 *     it is opt-in and cascades via an explicit "also rename song refs"
12	 *     checkbox.
13	 *   - Delete refuses if any song still references the abbreviation.
14	 *   - DisplayOrder is seeded by migrate-account-sync.php; the UI writes
15	 *     back whole-table updates so reordering is atomic.
16	 */
17	
18	require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
19	require_once dirname(__DIR__) . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'db_mysql.php';
20	require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'songbook-palette.php';
21	/* Shared validators (#719 PR 2a) — same rules used by the admin_songbook_*
22	   API endpoints in /api.php. Single source of truth so a tweak to the
23	   abbrev / colour / IETF-tag grammar lands on both surfaces in one go. */
24	require_once dirname(__DIR__) . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'songbook_validation.php';
25	
26	if (!isAuthenticated()) {
27	    header('Location: /manage/login');
28	    exit;
29	}
30	$currentUser = getCurrentUser();
31	if (!$currentUser || !userHasEntitlement('manage_songbooks', $currentUser['role'] ?? null)) {
32	    http_response_code(403);
33	    echo '<!DOCTYPE html><html><body><h1>403 — manage_songbooks required</h1></body></html>';
34	    exit;
35	}
36	$activePage = 'songbooks';
37	
38	$error   = '';
39	$success = '';
40	$db      = getDbMysqli();
41	
42	/* ---- GET ?action=pick_colour&abbr=XX (#772) -----------------------------
43	 * JSON helper for the edit-songbook modal's "Pick distinctive colour"
44	 * button. Calls pickAutoSongbookColour() to choose a hex that isn't
45	 * already in use by any other songbook (the picker reads tblSongbooks
46	 * itself to compute the avoid-set, so the result is guaranteed
47	 * distinctive across the live catalogue). Empty / missing abbr falls
48	 * back to a generic seed so a brand-new songbook in the create form
49	 * can still get a suggestion.
50	 *
51	 * Admin role required — same gate as the bulk auto-colour actions.
52	 * ----------------------------------------------------------------------- */
53	if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
54	    && ($_GET['action'] ?? '') === 'pick_colour'
55	) {
56	    header('Content-Type: application/json; charset=UTF-8');
57	    header('Cache-Control: no-store');
58	    if (!in_array(($currentUser['role'] ?? ''), ['admin', 'global_admin'], true)) {
59	        http_response_code(403);
60	        echo json_encode(['error' => 'Admin role required.']);
61	        exit;
62	    }
63	    $abbr = trim((string)($_GET['abbr'] ?? ''));
64	    if ($abbr === '') {
65	        /* Use a 6-char random seed so a fresh-songbook caller still
66	           gets a distinctive suggestion via the hash fallback path. */
67	        $abbr = substr(bin2hex(random_bytes(3)), 0, 6);
68	    }
69	    try {
70	        require_once __DIR__ . DIRECTORY_SEPARATOR
71	            . 'includes' . DIRECTORY_SEPARATOR
72	            . 'songbook-palette.php';
73	        $hex = pickAutoSongbookColour($db, $abbr);
74	        echo json_encode(['colour' => $hex]);
75	    } catch (\Throwable $e) {
76	        error_log('[manage songbooks pick_colour] ' . $e->getMessage());
77	        http_response_code(500);
78	        echo json_encode(['error' => 'Could not pick a colour.']);
79	    }
80	    exit;
81	}
82	
83	/* ---- GET ?action=script_search&q=… (#681 / renamed table in #738) ------
84	 * JSON typeahead for the IETF BCP 47 picker's Script field. Matches
85	 * substring (LIKE %q%) against tblLanguageScripts.Name OR
86	 * tblLanguageScripts.Code so a curator can search either by friendly
87	 * name ("Latin") or by ISO 15924 code ("Latn"). Empty query → empty
88	 * list; pre-migration deployments → empty list with a `note` rather
89	 * than a 500. Probes BOTH the new and legacy names so a deployment
90	 * mid-migration (rename pending) still serves suggestions.
91	 * ----------------------------------------------------------------------- */
92	if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
93	    && ($_GET['action'] ?? '') === 'script_search'
94	) {
95	    header('Content-Type: application/json; charset=UTF-8');
96	    header('Cache-Control: no-store');
97	    $q     = trim((string)($_GET['q'] ?? ''));
98	    $limit = max(1, min(50, (int)($_GET['limit'] ?? 20)));
99	    if ($q === '') {
100	        echo json_encode(['suggestions' => []]);
101	        exit;
102	    }
103	
104	    $tableName = '';
105	    try {
106	        /* Prefer the renamed table (#738); fall back to the legacy
107	           name if a deployment hasn't applied the rename yet. */
108	        foreach (['tblLanguageScripts', 'tblScripts'] as $candidate) {
109	            $probe = $db->prepare(
110	                "SELECT 1 FROM INFORMATION_SCHEMA.TABLES
111	                  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? LIMIT 1"
112	            );
113	            $probe->bind_param('s', $candidate);
114	            $probe->execute();
115	            $found = $probe->get_result()->fetch_row() !== null;
116	            $probe->close();
117	            if ($found) { $tableName = $candidate; break; }
118	        }
119	    } catch (\Throwable $e) {
120	        error_log('[script_search] probe failed: ' . $e->getMessage());
121	    }
122	    if ($tableName === '') {
123	        echo json_encode([
124	            'suggestions' => [],
125	            'note'        => 'tblLanguageScripts not yet created — run /manage/setup-database',
126	        ]);
127	        exit;
128	    }
129	
130	    try {
131	        $like = '%' . $q . '%';
132	        /* Identifier built from the allowlisted probe above — never
133	           user input, so no SQL injection surface. */
134	        $stmt = $db->prepare(
135	            "SELECT Code AS code, Name AS name, NativeName AS nativeName
136	               FROM {$tableName}
137	              WHERE IsActive = 1
138	                AND (Name LIKE ? OR Code LIKE ?)
139	              ORDER BY Name ASC
140	              LIMIT ?"
141	        );
142	        $stmt->bind_param('ssi', $like, $like, $limit);
143	        $stmt->execute();
144	        $res = $stmt->get_result();
145	        $suggestions = [];
146	        while ($row = $res->fetch_assoc()) {
147	            $suggestions[] = [
148	                'code'       => (string)$row['code'],
149	                'name'       => (string)$row['name'],
150	                'nativeName' => (string)$row['nativeName'],
151	            ];
152	        }
153	        $stmt->close();
154	        echo json_encode(['suggestions' => $suggestions], JSON_UNESCAPED_UNICODE);
155	    } catch (\Throwable $e) {
156	        error_log('[script_search] ' . $e->getMessage());
157	        http_response_code(500);
158	        echo json_encode(['error' => 'Search failed.']);
159	    }
160	    exit;
161	}
162	
163	/* ---- GET ?action=region_search&q=… (#681) ------------------------------
164	 * Same shape as script_search, against tblRegions. Codes are
165	 * uppercase ISO 3166-1 alpha-2 (or 3-digit M.49 numeric area codes
166	 * for groupings like 419 = Latin America), so the typeahead matches
167	 * either Name or Code as the user types.
168	 * ----------------------------------------------------------------------- */
169	if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
170	    && ($_GET['action'] ?? '') === 'region_search'
171	) {
172	    header('Content-Type: application/json; charset=UTF-8');
173	    header('Cache-Control: no-store');
174	    $q     = trim((string)($_GET['q'] ?? ''));
175	    $limit = max(1, min(50, (int)($_GET['limit'] ?? 20)));
176	    if ($q === '') {
177	        echo json_encode(['suggestions' => []]);
178	        exit;
179	    }
180	
181	    $hasTable = false;
182	    try {
183	        $probe = $db->prepare(
184	            "SELECT 1 FROM INFORMATION_SCHEMA.TABLES
185	              WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'tblRegions' LIMIT 1"
186	        );
187	        $probe->execute();
188	        $hasTable = $probe->get_result()->fetch_row() !== null;
189	        $probe->close();
190	    } catch (\Throwable $e) {
191	        error_log('[region_search] probe failed: ' . $e->getMessage());
192	    }
193	    if (!$hasTable) {
194	        echo json_encode([
195	            'suggestions' => [],
196	            'note'        => 'tblRegions not yet created — run /manage/setup-database',
197	        ]);
198	        exit;
199	    }
200	
201	    try {
202	        $like = '%' . $q . '%';
203	        $stmt = $db->prepare(
204	            'SELECT Code AS code, Name AS name
205	               FROM tblRegions
206	              WHERE IsActive = 1
207	                AND (Name LIKE ? OR Code LIKE ?)
208	              ORDER BY Name ASC
209	              LIMIT ?'
210	        );
211	        $stmt->bind_param('ssi', $like, $like, $limit);
212	        $stmt->execute();
213	        $res = $stmt->get_result();
214	        $suggestions = [];
215	        while ($row = $res->fetch_assoc()) {
216	            $suggestions[] = [
217	                'code' => (string)$row['code'],
218	                'name' => (string)$row['name'],
219	            ];
220	        }
221	        $stmt->close();
222	        echo json_encode(['suggestions' => $suggestions], JSON_UNESCAPED_UNICODE);
223	    } catch (\Throwable $e) {
224	        error_log('[region_search] ' . $e->getMessage());
225	        http_response_code(500);
226	        echo json_encode(['error' => 'Search failed.']);
227	    }
228	    exit;
229	}
230	
231	/* ---- GET ?action=affiliation_search&q=… (#670) -------------------------
232	 * JSON typeahead endpoint for the Songbook edit modal's Affiliation
233	 * field. Returns up to `limit` matching rows from
234	 * tblSongbookAffiliations, ranked by current usage in tblSongbooks
235	 * (most-cited first) so a curator's recent additions surface
236	 * straight away. Same auth gate as the page itself
237	 * (`manage_songbooks` entitlement); returns an empty list rather
238	 * than 4xx when the query is empty so the caller's onInput handler
239	 * stays trivial. Exits early so no page HTML follows.
240	 * ----------------------------------------------------------------------- */
241	if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
242	    && ($_GET['action'] ?? '') === 'affiliation_search'
243	) {
244	    header('Content-Type: application/json; charset=UTF-8');
245	    header('Cache-Control: no-store');
246	    $q     = trim((string)($_GET['q'] ?? ''));
247	    $limit = max(1, min(50, (int)($_GET['limit'] ?? 20)));
248	
249	    /* Empty query → empty list. We don't 400 because the typeahead
250	       calls this on every keystroke, including the first one before
251	       the user has typed anything. */
252	    if ($q === '') {
253	        echo json_encode(['suggestions' => []]);
254	        exit;
255	    }
256	
257	    /* Probe whether the registry table exists yet. New deployments
258	       that haven't run migrate-songbook-affiliations.php should not
259	       see a 500 — return an empty list and log a server-side note so
260	       the migration prompt on /manage/setup-database is the cure. */
261	    $hasRegistry = false;
262	    try {
263	        $probe = $db->prepare(
264	            "SELECT 1 FROM INFORMATION_SCHEMA.TABLES
265	              WHERE TABLE_SCHEMA = DATABASE()
266	                AND TABLE_NAME = 'tblSongbookAffiliations' LIMIT 1"
267	        );
268	        $probe->execute();
269	        $hasRegistry = $probe->get_result()->fetch_row() !== null;
270	        $probe->close();
271	    } catch (\Throwable $e) {
272	        error_log('[affiliation_search] probe failed: ' . $e->getMessage());
273	    }
274	    if (!$hasRegistry) {
275	        echo json_encode([
