3	declare(strict_types=1);
4	
5	/**
6	 * iHymns — Admin: Tags & Themes (#770)
7	 *
8	 * Catalogue-wide CRUD for tblSongTags + a merge flow for collapsing
9	 * duplicate-meaning tags into one canonical row. Mirrors the
10	 * /manage/languages scaffolding (PR #742) — list + filter + paginated
11	 * table + create / edit / delete / merge — plus the per-row usage
12	 * count that's specific to tags.
13	 *
14	 * Bug companion: the editor's tag-add path was firing a misleading
15	 * success toast even when the bulk_tag INSERT was no-op'd by the
16	 * tblSongTagMap → tblSongs FK on an unsaved song. That's fixed in
17	 * editor.js in the same PR; this page is the "where to merge a tag I
18	 * notice has a duplicate" surface that tag normalisation
19	 * (PR #763 / #762) feeds into.
20	 *
21	 * Auth: manage_tags entitlement (admin + global_admin).
