        $where[] = "s.SongbookAbbr = ?";
        $params[] = $songbookId;
        $types .= 's';
    }

    if (APP_CONFIG['features']['public_domain_only'] ?? false) {
        $where[] = "s.LyricsPublicDomain = 1";

